 {const na=ac||(dark?p.pink:p.acc||'#121212'),n=parseInt(na.slice(1),16),l=((n>>16)*.299+(n>>8&255)*.587+(n&255)*.114)/255;st.setProperty('--nacc',na);st.setProperty('--nonacc',l<=.6?'#ffffff':'#161616')}
